ALTER TABLE public.employees ADD COLUMN nome text;
CREATE TABLE mise.checklist_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nome text NOT NULL,modulo text NOT NULL DEFAULT 'RITMO',tipo text NOT NULL DEFAULT 'abertura',unit_id uuid,ativo boolean DEFAULT true,descricao text,categoria text);
CREATE TABLE mise.checklist_template_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),template_id uuid REFERENCES mise.checklist_templates,ordem int,titulo text NOT NULL,tipo_resposta text DEFAULT 'sim_nao',topico_ordem int,topico_nome text,peso numeric DEFAULT 1,critico bool DEFAULT false,requer_comentario text DEFAULT 'nao',requer_foto text DEFAULT 'nao');
CREATE TABLE mise.checklist_template_topicos(id uuid DEFAULT gen_random_uuid(),template_id uuid,topico_ordem int,topico_nome text,peso numeric DEFAULT 1);
CREATE TABLE mise.checklist_executions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),template_id uuid REFERENCES mise.checklist_templates,unit_id uuid,status text DEFAULT 'em_andamento',pontuacao_total numeric,pontuacao_obtida numeric,percentual numeric,concluido_em timestamptz,geo_fim_lat numeric,geo_fim_lng numeric);
CREATE TABLE mise.checklist_responses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),execution_id uuid REFERENCES mise.checklist_executions,item_id uuid REFERENCES mise.checklist_template_items,resposta jsonb,nao_aplicavel bool NOT NULL DEFAULT false,comentario text,foto_url text,respondido_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE mise.checklist_execution_topicos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),execution_id uuid REFERENCES mise.checklist_executions,topico_ordem int,topico_nome text,percentual numeric,zerado_por_critico bool NOT NULL DEFAULT false,peso numeric,UNIQUE(execution_id,topico_ordem));
CREATE TABLE mise.crivo_plano_acao(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),execution_id uuid REFERENCES mise.checklist_executions,response_id uuid REFERENCES mise.checklist_responses,descricao text NOT NULL,orientacao text,responsavel_nome text,responsavel_employee_id uuid,prazo date,status text NOT NULL DEFAULT 'aberto' CHECK(status IN ('aberto','em_andamento','resolvido','cancelado')),resolvido_em timestamptz,resolvido_por uuid,evidencia_url text,created_at timestamptz DEFAULT now());
